//! Golden-vector conformance: fixtures generated by C++ libtorrent v2.1.2
//! (`tools/golden_vectors/generate.cpp`). `resume_empty`/`resume_buf_empty`
//! pin `write_resume_data` wire output; `torrent_v1_synthetic` pins
//! `create_torrent`/`torrent_info` parsing.
#![allow(clippy::field_reassign_with_default)]
use bitdaemon_bencode::{Entry, bdecode};
use bitdaemon_common::flags::TorrentFlags;
use bitdaemon_common::types::DownloadPriority;
use bitdaemon_common::{Sha1Hash, Sha256Hash};
use bitdaemon_core::add_torrent_params::AddTorrentParams;
use bitdaemon_core::resume_data::{read_resume_data, write_resume_data_buf};
use bitdaemon_core::torrent_info::{LoadTorrentLimits, load_torrent};

fn fixture(name: &str) -> Vec<u8> {
    std::fs::read(format!("tests/data/{name}.bin")).expect("fixture")
}

/// The C++ fixture was produced from this exact params set — feeding the
/// same params through `write_resume_data_buf` must yield bytes that
/// decode to the same dict.
#[test]
fn golden_resume_empty() {
    let cpp_bytes = fixture("resume_empty");
    let cpp_node = bdecode(&cpp_bytes);
    assert!(cpp_node.error().is_none());

    // reading upstream bytes must succeed and produce the same fields
    let atp = read_resume_data(&cpp_bytes, &LoadTorrentLimits::default())
        .expect("upstream resume data must decode");
    assert_eq!(atp.name, b"fixture");
    assert_eq!(
        atp.trackers,
        vec![
            b"http://t1/announce".to_vec(),
            b"http://t2/announce".to_vec()
        ]
    );
    assert_eq!(atp.tracker_tiers, vec![0, 1]);
    assert_eq!(
        atp.file_priorities,
        vec![DownloadPriority(4), DownloadPriority(0)]
    );

    // our writer, fed the same params, must produce a dict that decodes
    // back to the same ATP (byte-exactness is pinned by the
    // `resume_buf_empty` fixture below).
    let our_buf = write_resume_data_buf(&atp);
    let roundtrip = read_resume_data(&our_buf, &LoadTorrentLimits::default())
        .expect("own resume data must re-decode");
    assert_eq!(roundtrip.name, atp.name);
    assert_eq!(roundtrip.trackers, atp.trackers);
    assert_eq!(roundtrip.tracker_tiers, atp.tracker_tiers);
    assert_eq!(roundtrip.file_priorities, atp.file_priorities);
}

/// `resume_buf_empty` is the raw `write_resume_data_buf` bytes from C++.
/// Byte-compare our writer's output for the params it decodes to —
/// the format contract is byte-level (ADR-0009).
#[test]
fn golden_resume_buf_empty_byte_compare() {
    let cpp_bytes = fixture("resume_buf_empty");
    let atp =
        read_resume_data(&cpp_bytes, &LoadTorrentLimits::default()).expect("fixture must decode");
    let ours = write_resume_data_buf(&atp);

    // Report dict-level diff before the byte assert for debuggability.
    let cpp_e = Entry::from(&bdecode(&cpp_bytes));
    let our_e = Entry::from(&bdecode(&ours));
    assert_eq!(cpp_e, our_e, "decoded resume dicts differ");
    assert_eq!(ours, cpp_bytes, "resume bytes differ from upstream v2.1.2");
}

/// C++ `create_torrent` + `set_piece_hashes` over a 27-byte `a.txt`.
/// Parsing must succeed and the info dict must hash-stably survive.
#[test]
fn golden_torrent_v1_synthetic() {
    let buf = fixture("torrent_v1_synthetic");
    let atp = load_torrent(&buf).expect("upstream .torrent must parse");
    let ti = atp.ti.expect("torrent_info");
    assert!(ti.is_valid());
    assert!(ti.v1());
    assert_eq!(ti.files().num_files(), 1);
    assert_eq!(ti.files().total_size(), 27);
    assert_eq!(ti.num_pieces(), 1);
    // v1 info-hash pins the exact bencoded info dict upstream produced
    assert!(ti.info_hash_v1().is_some());
}

/// BEP-52 v2-only torrent (merkle, `meta version` 2, 25-byte `b.bin`).
#[test]
fn golden_torrent_v2_synthetic() {
    let buf = fixture("torrent_v2_synthetic");
    let atp = load_torrent(&buf).expect("upstream v2 .torrent must parse");
    let ti = atp.ti.expect("torrent_info");
    assert!(ti.is_valid());
    assert!(ti.v2());
    assert!(!ti.v1());
    // upstream inserts a pad file to piece-align `b.bin` — num_files
    // counts it, same as upstream's file_storage.
    assert_eq!(ti.files().num_files(), 2);
    assert_eq!(ti.files().file_size(bitdaemon_common::FileIndex(0)), 25);
    assert_eq!(
        ti.files().file_name(bitdaemon_common::FileIndex(0)),
        b"b.bin"
    );
    assert!(ti.info_hash_v2().is_some());
}

/// `generate_fingerprint` output — `-XXNNNN-` peer-id prefix.
#[test]
fn golden_fingerprint() {
    assert_eq!(
        bitdaemon_core::fingerprint::Fingerprint::generate(b"BD", 0, 1, 0, 0),
        fixture("fingerprint_bd0100")
    );
    assert_eq!(
        bitdaemon_core::fingerprint::Fingerprint::generate(b"LT", 2, 1, 2, 0),
        fixture("fingerprint_lt2120")
    );
}

/// `make_magnet_uri` — exact parameter order and escaping.
#[test]
fn golden_magnet_hybrid() {
    let mut p = AddTorrentParams::default();
    p.name = b"fixture".to_vec();
    p.info_hashes.v1 = Sha1Hash::from_bytes(b"01234567890123456789").unwrap();
    p.info_hashes.v2 = Sha256Hash::from_bytes(b"01234567890123456789012345678901").unwrap();
    p.trackers = vec![
        b"http://t1/announce".to_vec(),
        b"udp://t2:443/announce".to_vec(),
    ];
    p.url_seeds = vec![b"http://ws/files/".to_vec()];

    let uri = bitdaemon_core::magnet_uri::make_magnet_uri(&p);
    let expect = String::from_utf8(fixture("magnet_hybrid")).unwrap();
    assert_eq!(uri, expect);

    // upstream URI must parse back to the same fields
    let parsed = bitdaemon_core::magnet_uri::parse_magnet(uri.as_bytes()).expect("magnet parses");
    assert_eq!(parsed.info_hashes, p.info_hashes);
    assert_eq!(parsed.name, p.name);
    assert_eq!(parsed.trackers, p.trackers);
    assert_eq!(parsed.url_seeds, p.url_seeds);
}

/// `resume_rich` — seed_mode + counters + limits, from C++
/// `write_resume_data` on a fully populated `add_torrent_params`.
#[test]
fn golden_resume_rich() {
    let cpp_bytes = fixture("resume_rich");
    let atp = read_resume_data(&cpp_bytes, &LoadTorrentLimits::default())
        .expect("upstream resume data must decode");
    assert_eq!(atp.name, b"rich");
    assert_eq!(atp.total_uploaded, 1024);
    assert_eq!(atp.total_downloaded, 2048);
    assert_eq!(atp.upload_limit, 5000);
    assert_eq!(atp.download_limit, 8000);
    assert_eq!(atp.max_connections, 50);
    assert_eq!(atp.max_uploads, 12);
    assert_eq!(atp.num_complete, 42);
    assert_eq!(atp.num_incomplete, 13);
    assert_eq!(atp.num_downloaded, 9);
    assert_eq!(atp.save_path, b"C:/downloads");
    assert!(atp.flags.contains(TorrentFlags::SEED_MODE));
    assert!(atp.flags.contains(TorrentFlags::AUTO_MANAGED));
    assert!(atp.flags.contains(TorrentFlags::SEQUENTIAL_DOWNLOAD));
    assert!(atp.flags.contains(TorrentFlags::DISABLE_DHT));

    // re-writing the same params must byte-match upstream output
    let ours = write_resume_data_buf(&atp);
    assert_eq!(
        Entry::from(&bdecode(&ours)),
        Entry::from(&bdecode(&cpp_bytes)),
        "decoded dicts differ"
    );
    assert_eq!(ours, cpp_bytes, "bytes differ from upstream v2.1.2");
}
